/* Lumen Fidei — deep comparative concept exhibits.
   Primary texts are privileged; confessions and classic theological syntheses
   are used to make each tradition internally intelligible before comparison. */
(function (global) {
  'use strict';
  const S = (author,title,href,note) => ({author,title,href,note});
  const T = (key,name,thesis,account,argument,objection,response,figures) => ({key,name,thesis,account,argument,objection,response,figures});
  const H = (date,title,significance,extra,figureId) => ({date,title,significance,extra,figureId});

  const D = {
    eucharist:{domain:'Sacraments & Worship',title:'Eucharist',centralQuestion:'What happens when the Church gathers around the table of the Lord?',definition:'The Eucharist is the Christian mystery of communion in which the Church obeys Christ’s command, gives thanks, remembers His Passion, receives His Body and Blood, and is gathered into His life. The central dispute is not whether the Supper matters, but what Christ gives, how He is present, whether the Eucharist is sacrificial, and what kind of communion it creates.',lead:'The Eucharist is one of the strongest places where theology becomes visible. The words of institution, the sacrificial language of the liturgy, Paul’s teaching about communion in 1 Corinthians, and the early Fathers all resist reducing the Supper to a private devotional exercise. Yet the traditions explain the mystery differently: Catholic and Orthodox theology confess sacramental realism and Eucharistic sacrifice; Lutheran theology confesses Christ’s true presence; Reformed theology teaches real spiritual participation; memorialist Protestant traditions emphasize remembrance and proclamation.',questions:['What does “This is my body” mean?','Is Christ truly present, and if so how?','Is the Eucharist a sacrifice?','Does the communicant receive Christ objectively or only through faith?','How does Eucharist make the Church?'],traditions:[
      T('catholic','Catholic','Real Presence, transubstantiation, and sacramental sacrifice belong together.',[
        'The Catholic Church teaches that Christ is truly, really, and substantially present under the appearances of bread and wine. At consecration, the substance of bread and wine becomes the substance of Christ’s Body and Blood while the sensible appearances remain. The doctrine of transubstantiation is therefore an explanation of what the Church confesses, not a claim that the Eucharist looks physically different.',
        'The Mass is sacrificial because Christ’s one sacrifice is made sacramentally present. Calvary is not repeated and Christ is not killed again. The Eucharistic liturgy makes present the one offering of the crucified and risen Christ, and the Church is drawn into that offering. Communion therefore unites the believer to Christ and, through Christ, to the Church.',
        'The Eucharist also has an ecclesial and eschatological dimension. The Church receives what it is: the Body of Christ is given so that the members may become more deeply one Body. The Eucharist anticipates the heavenly banquet while remaining rooted in the historical Passion and Resurrection.'
      ],'Catholic reasoning begins with the realism of Christ’s words and the Church’s ancient worship. If Christ gives His Body and Blood as the covenant meal, the sacrament should not be reduced to a mental recollection. The sacrificial reading follows from the unity of Passover, Cross, Resurrection, and liturgy.', 'Reformed critics argue that transubstantiation imports metaphysics into a biblical mystery and that calling the Mass a sacrifice compromises the once-for-all sufficiency of Calvary. Memorialist Protestants press the same concern from a different direction.', 'Catholic theology answers that “once for all” is precisely why the Mass is not a second Calvary. The sacrifice is one; the sacramental mode of its presence is distinct. Transubstantiation protects the claim that Christ Himself, not merely an idea of Christ, is given.', ['Ignatius of Antioch','Cyril of Jerusalem','Thomas Aquinas','Council of Trent']),
      T('orthodox','Eastern Orthodox','The Eucharist is the true Body and Blood of Christ and the center of the Church’s life.',[
        'Orthodox worship treats the Eucharist as a mystery rather than as a problem to be solved by one explanatory mechanism. The Divine Liturgy gives thanks, recalls salvation history, invokes the Holy Spirit, offers the gifts, and receives Christ in communion. The Church is not merely gathered around a symbol; she becomes the Eucharistic people through participation in Christ.',
        'Orthodox theology freely uses sacrificial language. The Eucharist is connected to the one offering of Christ and to the heavenly worship in which the Church participates. The liturgy is anamnesis: not mere psychological recollection, but a liturgical making-present of God’s saving acts.',
        'The Eucharist is inseparable from baptism, chrismation, repentance, fasting, and the whole ascetical life. Communion is therefore neither an isolated individual transaction nor a badge of private spirituality; it is communion with Christ within His visible Church.'
      ],'The Orthodox approach protects the mystery by refusing to confuse sacramental realism with a claim that the elements must change in a manner accessible to ordinary physical inspection. The Eucharist is received as divine gift within the liturgy of the whole Church.', 'Some Western critics hear this language as insufficiently precise. Others worry that Eucharistic sacrifice sounds like a repetition of Calvary.', 'Orthodox theology responds that the liturgy does not add to Christ’s finished work. It is participation in the one Paschal mystery. The Eucharist is precisely effective because Christ’s unique sacrifice remains the source of the Church’s worship.', ['Ignatius of Antioch','Cyril of Jerusalem','John Chrysostom','Nicholas Cabasilas']),
      T('lutheran','Lutheran','Christ’s true Body and Blood are genuinely given with the bread and wine for the forgiveness of sins.',[
        'Lutheran confessions reject a merely symbolic Eucharist. Christ says “This is my body” and “This cup is the new testament in my blood,” and the sacrament is therefore a true means by which Christ gives Himself. The communicant receives Christ sacramentally with the bread and wine.',
        'Lutheran theology does not accept transubstantiation as necessary for confessing Real Presence. The Lutheran concern is the promise: Christ is really present because He has pledged Himself to the sacrament. The Supper is therefore Gospel in sacramental form, giving forgiveness and strengthening faith.',
        'The Lutheran rejection of the Roman Mass as a propitiatory sacrifice does not mean the Supper is empty of sacrificial language. Christians offer thanksgiving and praise, but Christ’s once-for-all sacrifice is not repeated or supplemented.'
      ],'The Lutheran argument is intensely Christological and pastoral: the sacrament should be trusted because Christ promises it, not because believers can explain the mechanism by which He is present.', 'Reformed theology objects to an overly corporeal account, while Catholic theology argues that Lutheranism stops short of the full sacrificial and ontological implications of Eucharistic realism.', 'Lutherans answer that the sacrament’s efficacy rests on Christ’s institution and promise. The question is not how human metaphysics can contain Christ, but whether Christ is faithful to His Word.', ['Martin Luther','Philip Melanchthon','Formula of Concord']),
      T('reformed','Reformed','Believers truly commune with Christ in the Supper through the Holy Spirit, without a local bodily presence in the elements.',[
        'Calvin rejects both bare memorialism and the claim that Christ’s human body becomes locally present in the bread. Christ’s glorified humanity remains in heaven, yet the Spirit genuinely lifts believers into communion with Christ. The Supper therefore communicates Christ rather than merely representing Him.',
        'The bread and wine are signs and seals. They do not possess an independent magical power; the Spirit uses them to strengthen faith in the promises of the Gospel. The Supper is consequently a covenantal meal, ecclesial act, and means of grace.',
        'The Reformed tradition also rejects the Mass as a propitiatory sacrifice. Christ’s sacrifice is complete. The Eucharist is thanksgiving, remembrance, covenant communion, and participation in Christ’s benefits.'
      ],'The Reformed account seeks to preserve both Christ’s true gift and the integrity of His ascended humanity. The Spirit, not a change of the elements, establishes the communion.', 'Catholic and Lutheran critics argue that this risks making Christ’s presence dependent on the communicant’s faith or reducing sacramental realism to an inward experience.', 'Reformed theology distinguishes subjective faith from objective sacramental promise while maintaining that the benefits are received through Spirit-enabled faith. The sign is not empty; it is a divinely appointed instrument.', ['John Calvin','Ursinus','Westminster Assembly'])
    ],clashes:['Transubstantiation versus sacramental union versus spiritual presence versus memorial interpretation.','The Eucharist as sacramental sacrifice versus a thanksgiving meal that does not offer Christ.','Objective sacramental gift versus the role of faith in reception.','Whether Eucharistic communion is constitutive of the visible Church or chiefly an ordinance of an already constituted congregation.'],history:[H('c. 107','Ignatius of Antioch','Ignatius calls the Eucharist the flesh of Christ and connects Eucharistic unity with episcopal communion.','His letters are among the earliest post-apostolic witnesses against a purely symbolic reading.'),H('c. 180','Irenaeus','Irenaeus argues that the Eucharistic gifts are not ordinary food and connects them to resurrection.','His sacramental realism is embedded in his doctrine of creation, Incarnation, and bodily resurrection.'),H('c. 350','Cyril of Jerusalem','Mystagogical catecheses teach believers to receive the Eucharist as Christ’s Body and Blood.','The liturgical and catechetical tradition develops a strong sacramental realism.'),H('1215','Fourth Lateran Council','The term transubstantiation receives conciliar definition in the Latin West.','The Council gives a precise metaphysical formulation to a doctrine whose roots are much older.'),H('1551','Council of Trent','Trent defines Real Presence, transubstantiation, and the sacrificial character of the Mass.','Its Eucharistic decrees respond directly to Reformation controversies.'),H('1529–1580','Reformation confessions','Lutheran, Reformed, and other Protestant confessions develop distinct accounts of the Supper.','The Reformation disagreement is therefore not one Protestant Eucharistic position but several.' )],sources:[S('Ignatius of Antioch','Letter to the Smyrnaeans','https://www.newadvent.org/fathers/0109.htm','Primary'),S('Justin Martyr','First Apology','https://www.newadvent.org/fathers/0126.htm','Primary'),S('Cyril of Jerusalem','Mystagogical Catecheses','https://www.newadvent.org/fathers/3101.htm','Primary'),S('Thomas Aquinas','Summa Theologiae III, qq.73–83','texts/summa.html?part=tertia&q=73&a=1','Primary'),S('John Calvin','Institutes IV.17','https://www.ccel.org/ccel/calvin/institutes.iv.xvii.html','Primary'),S('Augsburg Confession','Article X','https://bookofconcord.org/augsburg-confession/chief_articles/article_x/','Confession'),S('Westminster Confession','Chapter 29','https://wts.edu/wcf','Confession'),S('Catechism of the Catholic Church','§§1322–1419','https://www.vatican.va/content/catechism/en/part_two/section_two/chapter_one/article_3.html','Secondary synthesis')]},

    trinity:{domain:'God',title:'Trinity',centralQuestion:'How can Christians confess one God while worshipping Father, Son, and Holy Spirit?',definition:'The Trinity is the confession that the one God is eternally Father, Son, and Holy Spirit: three distinct divine Persons who possess the one undivided divine nature. Christianity rejects both tritheism and the reduction of the Persons to temporary modes of one subject.',lead:'The doctrine is not presented in Scripture as a single technical formula. It emerges from the Church’s simultaneous confession of the Father as God, the Son as God, and the Spirit as God, together with the conviction that there is only one God. Nicaea and Constantinople establish the creedal boundaries; the Cappadocians clarify person and essence; Augustine and Aquinas develop Latin accounts; the East–West dispute over the Filioque concerns the Spirit’s eternal procession and, more broadly, the grammar of Trinitarian theology.',questions:['What does “one essence, three Persons” mean?','How are the divine Persons distinct without becoming three gods?','What does the Father’s monarchy mean?','How does the Spirit proceed?','Does the Filioque change the doctrine or merely clarify it?'],traditions:[
      T('catholic','Catholic','One divine essence subsisting in three Persons; the Spirit proceeds eternally from the Father and the Son as from one principle.',[
        'Latin theology speaks of one simple divine essence and real relations of origin. The Father is unbegotten; the Son is eternally begotten; the Spirit eternally proceeds. The Persons are not three centers of being alongside one another, but the one God subsisting in three relations.',
        'Augustine’s De Trinitate emphasizes that the divine unity is not a society of three gods. Aquinas later explains the processions of Word and Love and uses the language of relations to distinguish Persons without dividing the divine substance.',
        'The Filioque is confessed in the Latin Creed: the Spirit proceeds from the Father and the Son. Catholic theology interprets this as one procession from the Father through the Son or from Father and Son as one principle, not as two independent sources.'
      ],'The Western argument seeks to account for the intimate relation between Son and Spirit without sacrificing monotheism. The Spirit is the Spirit of the Son as well as of the Father in the biblical economy, and Latin theology believes the eternal doctrine can legitimately express this.', 'Orthodox critics argue that the unilateral addition to the Creed and the language of two principles compromise the Father’s monarchy and disturb the relational structure expressed by the Greek Fathers.', 'Catholic theology responds that the Filioque does not posit two sources and that the Father remains the ultimate source of the divine life. The disagreement therefore includes both theological content and ecclesial questions about changing a universal Creed.', ['Augustine','Thomas Aquinas','Council of Florence']),
      T('orthodox','Eastern Orthodox','One God, the Father as the personal source; the Son is eternally begotten and the Spirit eternally proceeds from the Father.',[
        'The Cappadocian synthesis distinguishes ousia and hypostasis without making the Persons three separate beings. The Father is the personal arche: the Son and Spirit have the same divine nature but receive their personal existence in different relations to the Father.',
        'Orthodox theology rejects the Filioque as a legitimate alteration of the Nicene-Constantinopolitan Creed and generally refuses to describe the Son as a second cause of the Spirit. The Spirit is eternally from the Father and is manifested through the Son.',
        'Later Orthodox theology, especially in the Palamite tradition, also distinguishes God’s essence from His energies. This is not a second Trinity but a way of affirming that God is truly communicable while His essence remains beyond creaturely comprehension.'
      ],'The Eastern concern is that Trinitarian theology must preserve the Father’s monarchy and the personal distinctions without allowing the divine essence to become an impersonal fourth reality.', 'Catholic theology argues that the Filioque can be expressed without denying the Father as source, and that the Latin and Greek formulations can be reconciled when “source” and “principle” are carefully distinguished.', 'Orthodox theologians maintain that the Creed should not have been altered unilaterally and that the Eastern formulation protects the patristic grammar more faithfully.', ['Basil the Great','Gregory Nazianzen','Gregory of Nyssa','John of Damascus','Gregory Palamas']),
      T('lutheran','Lutheran','The Reformation retains the Nicene doctrine of one God in three Persons and inherits the Western confession of the Spirit’s procession.',[
        'Lutheran confessions remain decisively catholic in Trinitarian doctrine. The Father, Son, and Spirit are consubstantial, eternal, and worthy of the same worship. The Trinity is received through Scripture and the ancient Creeds rather than reconstructed as a new Reformation doctrine.',
        'Lutheran theology emphasizes that the Triune God is known through His self-revelation in Christ and the Gospel. Speculation about God apart from His revealed Word is restrained; the Trinity is confessed because God has disclosed Himself as Father, Son, and Spirit.',
        'The doctrine is therefore inseparable from Christology and sacrament: baptism is into the one name of Father, Son, and Spirit, and salvation is the work of the Triune God.'
      ],'The Lutheran argument is confessional continuity: Reformation theology does not begin Christianity over again but reforms doctrine and worship while retaining the ancient catholic rule of faith.', 'Some Protestant theologians later challenged classical Trinitarianism, but such positions stand outside the Lutheran confessional mainstream.', 'The Lutheran confessions explicitly reject anti-Trinitarian readings and locate Protestant identity within Nicene Christianity.', ['Martin Luther','Philip Melanchthon','Book of Concord']),
      T('reformed','Reformed','The one Triune God is Father, Son, and Spirit; the divine Persons are distinct yet one in essence, will, power, and glory.',[
        'Reformed theology inherits Nicene and Augustinian Trinitarianism. Calvin stresses that Father, Son, and Spirit are not merely names for different divine activities; the distinctions are real and eternal.',
        'The Reformed tradition places particular weight on the economic revelation of the Trinity: the Father sends the Son, the Son accomplishes redemption, and the Spirit applies redemption. Yet these works are not separable acts of three independent gods; the one divine will operates in the inseparable operations of the Trinity.',
        'Classical Reformed confessions therefore affirm the Trinity while rejecting both modalism and tritheism. The Trinity is the grammar of salvation: the Father purposes, the Son redeems, and the Spirit unites believers to Christ.'
      ],'The Reformed account begins with the biblical economy of salvation and refuses to treat the Trinity as an abstract metaphysical appendix.', 'Eastern critics raise the same Filioque concerns as Catholic–Orthodox polemics, while modern critics sometimes argue that the classical doctrine exceeds explicit biblical terminology.', 'Reformed theology answers that the technical vocabulary protects truths already required by Scripture and the worship of the early Church.', ['John Calvin','Francis Turretin','Westminster Assembly'])
    ],clashes:['Father’s monarchy and the Filioque.','How “Person” differs from modern notions of an independent individual.','Whether Trinitarian technical language faithfully safeguards biblical worship or goes beyond Scripture.','How divine unity and personal distinction can both be absolute.'],history:[H('c. 100–200','Apostolic and sub-apostolic worship','Baptismal and doxological formulas place Father, Son, and Spirit together.','The Church worships in a Trinitarian pattern before the technical vocabulary is stabilized.'),H('325','Council of Nicaea','The Son is confessed as consubstantial with the Father.','Nicaea rejects Arius and establishes the boundary of orthodox Christology.'),H('381','Council of Constantinople','The Nicene confession is expanded and the Holy Spirit is confessed within the same divine worship.','The Creed becomes the central ecumenical Trinitarian confession.'),H('c. 370–400','The Cappadocians','Basil, Gregory Nazianzen, and Gregory of Nyssa clarify one essence and three hypostases.','Their vocabulary becomes foundational for Eastern Trinitarian theology.'),H('c. 400','Augustine, De Trinitate','Augustine develops a major Latin account of divine unity and relations.','His work profoundly shapes Western theology.'),H('1054–1439','Filioque controversy','The procession of the Spirit becomes a major East–West dispute.','The theological issue becomes inseparable from questions of ecclesial authority and the Creed.' )],sources:[S('Athanasius','Orations Against the Arians','https://www.newadvent.org/fathers/2816.htm','Primary'),S('Basil','On the Holy Spirit','https://www.newadvent.org/fathers/3203.htm','Primary'),S('Gregory Nazianzen','Theological Orations','https://www.newadvent.org/fathers/3102.htm','Primary'),S('Augustine','De Trinitate','https://www.newadvent.org/fathers/1301.htm','Primary'),S('John of Damascus','Exact Exposition of the Orthodox Faith','https://www.newadvent.org/fathers/3304.htm','Primary'),S('Thomas Aquinas','Summa I, qq.27–43','texts/summa.html?part=prima&q=27&a=1','Primary'),S('John Calvin','Institutes I.13','https://www.ccel.org/ccel/calvin/institutes.i.xiii.html','Primary'),S('Vladimir Lossky','The Mystical Theology of the Eastern Church','https://archive.org/details/mysticaltheology0000loss','Secondary synthesis')]},

    atonement:{domain:'Christology & Salvation',title:'Atonement',centralQuestion:'How does the death and resurrection of Christ reconcile humanity to God?',definition:'Atonement names the saving work of Christ by which sin, death, alienation, and the powers opposed to God are overcome. Scripture gives many images—sacrifice, Passover, ransom, victory, reconciliation, substitution, healing, and representation. Classical Christian traditions normally preserve several of these together, while differing over which logic should organize the explanation.',lead:'No single metaphor exhausts the Cross. Irenaeus emphasizes recapitulation, Athanasius victory over death and corruption, Anselm satisfaction, Thomas Aquinas a multi-dimensional synthesis, Luther the paradox of the Cross, and Calvin penal substitution within a wider doctrine of union with Christ. The deepest common claim is that Christ saves objectively through His obedient life, death, and resurrection; the disagreement concerns what precisely is accomplished and how that accomplishment is communicated to believers.',questions:['What problem does the Cross solve?','Does Christ defeat death, satisfy justice, bear punishment, or all three?','Who receives the “ransom”?','How does Christ’s humanity heal human nature?','How is the objective work of Christ applied to believers?'],traditions:[
      T('catholic','Catholic','Christ’s sacrifice is the supreme act of obedience and love that reconciles humanity to God and opens participation in divine life.',[
        'Catholic theology does not require one exclusive theory of atonement. The Catechism gathers sacrifice, redemption, substitution, obedience, reconciliation, and love. Christ is the new Adam whose obedience reverses Adam’s disobedience; His Cross is both sacrifice and revelation of divine love.',
        'Anselm’s satisfaction account explains why sin is not trivial: the creature’s disorder cannot simply be ignored. Aquinas incorporates satisfaction into a larger account in which Christ’s Passion has infinite value because of the dignity of His Person and the perfection of His love.',
        'The Resurrection is essential. The Cross is not an isolated divine punishment but the Paschal mystery in which Christ passes through death and opens humanity to resurrection and communion with God.'
      ],'The Catholic synthesis resists reducing salvation to one mechanism. Justice, mercy, sacrifice, victory, and transformation belong together because the one Christ accomplishes one unified redemption.', 'Reformed theology can regard this synthesis as insufficiently sharp about punishment and imputation, while some Orthodox theologians regard Western satisfaction and penalty language as overly juridical.', 'Catholic theology answers that the Cross is juridical, sacrificial, victorious, and transformative at once; no single metaphor should control all the biblical evidence.', ['Augustine','Anselm','Thomas Aquinas','Council of Trent']),
      T('orthodox','Eastern Orthodox','Christ enters death, destroys its power, heals human nature, and unites humanity to divine life.',[
        'Eastern theology often begins with the existential enemies of humanity: corruption, death, slavery to sin, and separation from God. The Incarnation itself is therefore salvific. The Son assumes human nature so that human nature may be healed and raised.',
        'The Paschal victory is not merely a legal transaction. Christ enters the realm of death and destroys its dominion from within. The Cross and Resurrection together are the victory of divine life over death.',
        'The goal is theosis. Humanity is not merely released from punishment but restored to communion with God. This makes Incarnation, Cross, Resurrection, Ascension, Eucharist, and sanctification one continuous mystery.'
      ],'The Orthodox account reads the Cross through the Resurrection: the question is not only how guilt is removed but how death and corruption are conquered.', 'Western critics argue that Christus Victor can understate guilt and divine justice if detached from sacrifice and repentance.', 'Orthodox theology answers that sacrifice and judgment are present, but they should be interpreted within the larger biblical drama of life, death, victory, and communion rather than isolated as a mechanism of punishment.', ['Irenaeus','Athanasius','Gregory Nazianzen','Maximus the Confessor']),
      T('lutheran','Lutheran','Christ bears sin and judgment in the sinner’s place; the Cross is the decisive revelation of God’s saving promise.',[
        'Lutheran theology places strong emphasis on substitution, the bearing of sin, and Christ’s victory. The Cross reveals simultaneously the gravity of sin and the depth of divine mercy. Christ becomes the bearer of the curse so that sinners receive His righteousness.',
        'The theology of the Cross also has an epistemological dimension: God is known savingly not by human speculation about glory but in the crucified Christ. The Cross overturns human calculations about merit and power.',
        'The objective accomplishment of Christ is delivered through the Gospel and sacraments. The believer does not climb to Christ; Christ comes to the sinner in Word and sacrament.'
      ],'The Lutheran account protects the radical gratuity of salvation. If Christ truly bears the sinner’s judgment, there is no remaining debt that the sinner must pay to make the Cross effective.', 'Catholic and Orthodox critics can argue that a heavily forensic account risks making salvation primarily a change in legal status.', 'Lutheran theology responds that the forensic gift creates actual new life: justification and sanctification are distinct, but the Christ who justifies is the Christ who renews.', ['Martin Luther','Philip Melanchthon','Formula of Concord']),
      T('reformed','Reformed','Christ bears the penalty of sin as the substitute of His people and fulfills the covenant obedience humanity failed to render.',[
        'Reformed theology gives penal substitution a central role. Christ, the covenant head, obeys where Adam failed and bears the judgment due to sin. His righteousness is imputed to believers and received by faith.',
        'This is joined to union with Christ. Christ does not merely stand outside the believer as a legal substitute; by faith believers are united to Him, receiving justification and sanctification as distinct benefits of the same union.',
        'The Reformed tradition also retains Christus Victor, sacrifice, reconciliation, and victory over death. Penal substitution is central, but it is not necessarily the only biblical image.'
      ],'The Reformed argument emphasizes the moral seriousness of divine justice and the covenantal structure of Scripture. Sin incurs real guilt; Christ truly bears it.', 'Orthodox and some modern Catholic critics object that transferring punishment from guilty to innocent can appear incompatible with justice.', 'Reformed theology answers that Christ voluntarily identifies Himself with His people as covenant head and that substitution is grounded in divine self-giving, not an arbitrary third-party punishment.', ['John Calvin','Francis Turretin','John Owen','Westminster Assembly'])
    ],clashes:['Christus Victor, satisfaction, penal substitution, recapitulation, and moral influence as competing or complementary accounts.','Whether the primary problem is guilt, corruption, death, captivity, alienation, or all of these.','How divine justice and mercy are related at the Cross.','Whether salvation is best described juridically, ontologically, or as a unified Paschal mystery.'],history:[H('c. 180','Irenaeus and recapitulation','Christ sums up and renews humanity in Himself.','The Incarnation and obedience of Christ reverse Adam’s failure.'),H('c. 325','Athanasius','The Word assumes humanity to defeat corruption and death.','The Incarnation is itself inseparable from redemption.'),H('c. 1098','Anselm, Cur Deus Homo','Satisfaction becomes a major Western explanation of the Cross.','Anselm asks why the Incarnation and death of Christ are fitting within divine justice and order.'),H('c. 1265–1274','Thomas Aquinas','Aquinas integrates sacrifice, satisfaction, merit, obedience, and love.','The Cross has saving value through Christ’s Person and perfect charity.'),H('1518–1540','Reformation theology','Lutheran and Reformed writers develop distinct accounts of substitution, promise, and the Cross.','The Reformation makes justification and the sufficiency of Christ central to atonement debates.'),H('20th century','Modern retrievals','Scholars revisit Christus Victor, recapitulation, sacrifice, and substitution.','Contemporary theology often seeks a multi-metaphor account rather than one exclusive theory.')],sources:[S('Irenaeus','Against Heresies','https://www.newadvent.org/fathers/0103.htm','Primary'),S('Athanasius','On the Incarnation','https://www.newadvent.org/fathers/2802.htm','Primary'),S('Anselm','Cur Deus Homo','https://www.ccel.org/ccel/anselm/basic_works.html','Primary'),S('Thomas Aquinas','Summa III, qq.46–49','texts/summa.html?part=tertia&q=46&a=1','Primary'),S('Martin Luther','Heidelberg Disputation','https://bookofconcord.org/other-resources/heidelberg-disputation/','Primary'),S('John Calvin','Institutes II.16','https://www.ccel.org/ccel/calvin/institutes.ii.xvi.html','Primary'),S('Catechism of the Catholic Church','§§599–618','https://www.vatican.va/content/catechism/en/part_one/section_two/chapter_two/article_4/ii_died_crucified.html','Secondary synthesis'),S('Gustaf Aulén','Christus Victor','https://archive.org/details/christusvictoran0000aule','Secondary study')]},

    church:{domain:'Ecclesiology',title:'Church',centralQuestion:'What is the Church that Christ founded, and where is her visible unity?',definition:'The Church is the people gathered by God in Christ, the Body and Bride of Christ, temple of the Holy Spirit, apostolic community, sacramental assembly, and witness to the Kingdom. The great ecclesiological disputes concern visibility, apostolic succession, sacramental authority, primacy, councils, infallibility, and the relationship between local congregations and the universal Church.',lead:'Catholic, Orthodox, Lutheran, and Reformed traditions all confess one holy Christian Church, but they locate its visible unity differently. Catholicism identifies the fullness of ecclesial structure with communion under the bishops and the Bishop of Rome; Orthodoxy emphasizes Eucharistic communion among autocephalous Churches gathered in conciliarity; Lutheranism defines the Church around the pure preaching of the Gospel and right administration of the sacraments; Reformed theology emphasizes Word, sacrament, discipline, and covenant community.',questions:['Is the Church visible in a determinate institution?','What makes apostolic succession?','What is the role of bishops and councils?','Does the Bishop of Rome possess universal jurisdiction?','What constitutes a true local Church?'],traditions:[
      T('catholic','Catholic','The Church subsists as the visible communion of the baptized, bishops, sacraments, and the successor of Peter united in faith and charity.',[
        'Catholic ecclesiology joins the mystical Body with visible structure. Christ gives the Church apostles, bishops, sacraments, doctrine, and a visible principle of unity. The Church is therefore not merely the invisible totality of true believers.',
        'The Bishop of Rome has a unique Petrine office. Vatican I defines universal jurisdiction and papal infallibility under specific conditions, while Vatican II emphasizes episcopal collegiality and the Church as People of God and sacrament of salvation.',
        'Apostolic succession is not merely genealogical continuity. It is succession in ministry, doctrine, sacrament, and communion. The Church’s holiness is compatible with the presence of sinners among her members because her holiness comes from Christ.'
      ],'The Catholic argument emphasizes historical continuity: the Church visible in Acts, Ignatius, Irenaeus, and Cyprian is recognizably structured around bishops, Eucharist, doctrine, and communion.', 'Orthodox critics reject universal papal jurisdiction and later definitions of papal infallibility; Protestants argue that ecclesial authority must remain subordinate to the Gospel and Scripture.', 'Catholic theology responds that primacy serves visible unity and that Scripture itself depicts Peter with a distinctive pastoral role. Authority is not opposed to Scripture but ordered to preserving the apostolic deposit.', ['Ignatius of Antioch','Irenaeus','Cyprian','Thomas Aquinas','Vatican II']),
      T('orthodox','Eastern Orthodox','The Church is the Eucharistic and conciliar communion of apostolic Churches, united in the same faith, sacraments, and bishops.',[
        'Orthodox ecclesiology is strongly sacramental and Eucharistic. A local bishop gathers a real Church around the Eucharist, while the universal Church is the communion of such Churches in the apostolic faith.',
        'The Church is conciliar rather than centralized. The Ecumenical Councils are authoritative because they express the Church’s common confession under the guidance of the Spirit. The Bishop of Rome historically possessed primacy of honor, but Orthodox theology rejects the modern Catholic claim of universal ordinary jurisdiction.',
        'Apostolicity means continuity of faith and sacramental ministry. The Church is holy because Christ is holy, yet her members remain sinners who continually require repentance.'
      ],'The Orthodox argument sees conciliarity as intrinsic to the Church’s ancient structure. Primacy exists, but primacy must function within communion rather than above it.', 'Catholic theology argues that a merely conciliar model lacks a final visible principle of unity and cannot adequately explain the Petrine office.', 'Orthodox theology answers that the ecumenical councils and Eucharistic communion provide genuine visible unity without transforming one bishop into a universal monarch.', ['Ignatius of Antioch','Cyprian of Carthage','John Chrysostom','John Zizioulas']),
      T('lutheran','Lutheran','The Church is the assembly in which the Gospel is purely taught and the sacraments are rightly administered.',[
        'The Augsburg Confession defines the Church in relation to the means by which Christ gives salvation: the Gospel and sacraments. This does not make the Church invisible; congregations, ministers, public worship, and sacraments are real.',
        'The Lutheran distinction between the visible and invisible Church prevents ecclesial holiness from being confused with the moral perfection of every member. Christ’s Church can exist amid sinners because the Gospel remains present.',
        'Ordained ministry is important, but the minister’s authority derives from Christ’s institution of the means of grace rather than from a claim that a particular centralized jurisdiction is necessary for the Church to exist.'
      ],'The Lutheran argument makes the Gospel constitutive: where Christ’s saving Word is truly preached and His sacraments are rightly administered, the Church is genuinely present.', 'Catholic and Orthodox critics argue that this definition can make ecclesial unity too dependent on agreement about doctrine and too detached from historic episcopal structure.', 'Lutherans answer that apostolicity is first fidelity to the apostolic Gospel. Institutional continuity cannot rescue a Church that has lost the Gospel.', ['Martin Luther','Philip Melanchthon','Augsburg Confession']),
      T('reformed','Reformed','The true Church is marked by faithful preaching of the Word, right administration of the sacraments, and disciplined covenant life.',[
        'The Reformed tradition gives the Word a constitutive role. The Church is not defined by a particular episcopal polity but by fidelity to Christ’s Gospel. Calvin nevertheless treats the visible Church with seriousness and calls Christians to remain within it rather than constructing private religion.',
        'The sacraments are genuine means of grace and seals of God’s covenant. Church discipline is a third mark because the Church must visibly order life according to the Gospel.',
        'Presbyterian and continental Reformed traditions differ over polity, but they share the conviction that Christ alone is head of the Church and that ecclesial offices serve rather than replace His authority.'
      ],'The Reformed account seeks to preserve the Church’s visibility while preventing institutional structures from becoming independent sources of authority.', 'Catholic and Orthodox critics argue that separating apostolicity from historic episcopal succession weakens the Church’s visible continuity.', 'Reformed theology answers that succession without doctrinal fidelity is not true apostolicity. The apostolic Church is recognized by fidelity to apostolic teaching.', ['John Calvin','John Knox','Westminster Assembly'])
    ],clashes:['Papal primacy and universal jurisdiction versus conciliar primacy.','Apostolic succession as sacramental succession versus succession primarily in doctrine.','Whether the Church is identified by institutional communion, Eucharistic communion, or Word and sacrament.','The authority of councils, confessions, bishops, and Scripture.'],history:[H('c. 107','Ignatius of Antioch','Ignatius strongly connects bishop, Eucharist, and Church unity.','His letters provide a crucial early witness to episcopal ecclesiology.'),H('c. 180','Irenaeus','Apostolic succession and the rule of faith are used against Gnostic claims.','The Church’s public continuity becomes an argument for doctrinal continuity.'),H('c. 251','Cyprian','The episcopate and unity of the Church receive extensive theological treatment.','Cyprian’s ecclesiology becomes influential in both East and West.'),H('325–787','Ecumenical Councils','Councils become the major visible expression of universal doctrinal communion.','The conciliar model shapes Catholic and Orthodox ecclesiology.'),H('1054','East–West division','The separation of Rome and Constantinople changes the practical shape of Christian unity.','Later disputes about primacy deepen the ecclesiological divide.'),H('1517–1648','Reformation','Protestant churches redefine the marks and authority of the Church.','Word, sacrament, discipline, and confessional identity become central.'),H('1869–1965','Vatican I and II','Catholic ecclesiology articulates papal primacy, infallibility, collegiality, and the People of God.','The modern Catholic synthesis holds primacy and collegiality together.')],sources:[S('Ignatius of Antioch','Letter to the Smyrnaeans','https://www.newadvent.org/fathers/0109.htm','Primary'),S('Irenaeus','Against Heresies III','https://www.newadvent.org/fathers/0103303.htm','Primary'),S('Cyprian','On the Unity of the Catholic Church','https://www.newadvent.org/fathers/050701.htm','Primary'),S('Augsburg Confession','Article VII','https://bookofconcord.org/augsburg-confession/chief_articles/article_vii/','Confession'),S('Calvin','Institutes IV','https://www.ccel.org/ccel/calvin/institutes.iv.html','Primary'),S('Vatican II','Lumen Gentium','https://www.vatican.va/archive/hist_councils/ii_vatican_council/documents/vat-ii_const_19641121_lumen-gentium_en.html','Primary council'),S('Westminster Confession','Chapter 25','https://wts.edu/wcf','Confession'),S('John Zizioulas','Being as Communion','https://archive.org/details/beingascommunion0000zizi','Secondary Orthodox synthesis')]},

    'free-will':{domain:'Anthropology & Grace',title:'Free Will',centralQuestion:'What does it mean for a fallen human being to be free before God?',definition:'Christian teaching holds together divine providence and human responsibility. The difficulty is to describe freedom after the Fall: is the will wounded, enslaved, or radically unable to choose God without regeneration? And when grace acts, does it restore freedom, precede it, cooperate with it, or determine the successful response?',lead:'Augustine’s anti-Pelagian writings, the Eastern Fathers, Aquinas, Luther, Calvin, and later Protestant debates all wrestle with the same paradox: salvation is wholly dependent on grace, yet Scripture commands real repentance and faith. The traditions do not simply divide into “free” and “unfree.” They use different senses of freedom—freedom of choice, freedom from coercion, freedom from sin, and freedom for the good.',questions:['What was lost in the Fall?','Can the fallen will choose God?','What is prevenient grace?','Is freedom compatible with divine foreknowledge?','Does grace restore or replace human agency?'],traditions:[
      T('catholic','Catholic','Human freedom is wounded by sin but not destroyed; prevenient grace enables a real cooperation with God.',[
        'Catholic theology distinguishes natural freedom from supernatural capacity. The Fall wounds intellect and will and introduces concupiscence, but the image of God is not erased. The sinner cannot attain supernatural friendship by unaided nature, yet grace precedes and enables every salutary movement.',
        'Aquinas argues that divine causality does not compete with creaturely causality. God moves creatures according to their nature; therefore divine motion can be the cause of a free act rather than its negation.',
        'Catholic theology consequently rejects both Pelagian self-sufficiency and a deterministic picture in which human responsibility becomes unreal. Cooperation with grace is itself a gift.'
      ],'If God created rational creatures for love, salvation should heal rather than abolish their freedom. Divine sovereignty is understood as the deeper cause that enables creaturely freedom.', 'Reformed critics argue that this gives too much explanatory weight to cooperation and makes grace dependent on the human response.', 'Catholic theology answers that grace remains first in order of causality. The human response never becomes an independent source of salvation.', ['Augustine','Thomas Aquinas','Council of Trent']),
      T('orthodox','Eastern Orthodox','The image of God and human freedom remain after the Fall, though distorted by sin and death; salvation involves synergy with divine grace.',[
        'Eastern anthropology tends to describe the Fall less in terms of inherited guilt and more in terms of corruption, mortality, and bondage. Humanity remains capable of turning toward God, but the will is deeply damaged and cannot heal itself.',
        'Synergy means cooperation, not two equal powers negotiating salvation. God initiates, sustains, and empowers; the person responds freely. Ascetic practice is therefore meaningful because grace does not bypass the person.',
        'Theosis requires a genuinely personal response. Love cannot be coerced, and divine grace does not destroy the freedom it heals.'
      ],'The Orthodox concern is that salvation must remain relational. God does not save a person as an object but brings the person into living communion.', 'Reformed theology argues that the fallen will’s resistance is stronger than this account allows and that regeneration must precede any saving response.', 'Orthodox theology responds that irresistible grace can make the language of love and repentance difficult to preserve, while synergy better fits the Church’s liturgical and ascetic tradition.', ['John Chrysostom','John Cassian','Maximus the Confessor']),
      T('lutheran','Lutheran','The sinner cannot convert himself; saving faith is created by the Holy Spirit through the Gospel, yet grace may be resisted.',[
        'Luther’s Bondage of the Will distinguishes freedom in ordinary human affairs from the spiritual question of turning oneself toward God. The sinner cannot, by natural powers, produce faith or love of God.',
        'The Lutheran confessions therefore speak strongly about monergistic conversion. Faith is God’s gift. Yet Lutheranism does not conclude that grace is irresistible in every encounter: the Spirit’s work can be resisted, and unbelief is real.',
        'After conversion the believer genuinely acts and bears fruit. The distinction is between the origin of faith and the life that faith produces.'
      ],'The Lutheran concern is assurance: if conversion finally depends on a cooperation that the sinner supplies, the conscience can never know whether it has supplied enough.', 'Catholic and Orthodox critics argue that the Lutheran account risks making the human will passive beyond what Scripture’s exhortations require.', 'Lutherans answer that the commands reveal duty, while the Gospel gives what the command demands. The Spirit creates the response through the promise.', ['Martin Luther','Formula of Concord']),
      T('reformed','Reformed','Fallen humanity is unable to turn to God apart from regenerating grace; the regenerated will then believes freely.',[
        'Reformed theology describes total inability: sin affects every faculty, so the sinner does not naturally seek God as God requires. Election and regeneration therefore precede the decisive act of saving faith.',
        'This does not mean coercion. Effectual grace changes the heart so that the person willingly comes to Christ. Freedom is restored as freedom for the good, not preserved as the autonomous power to choose either God or evil with equal neutrality.',
        'The doctrine fits the Reformed order of salvation: election, effectual calling, regeneration, faith, justification, sanctification, perseverance.'
      ],'If the sinner can finally originate the decisive movement toward God, grace is no longer the deepest explanation of salvation. Reformed theology therefore makes regeneration causally prior.', 'Catholic, Orthodox, and Lutheran critics object that this can make the universal Gospel call difficult to reconcile with a particular effectual decree.', 'Reformed theology distinguishes the universal external call from the inward effectual call and insists that both are genuine. The moral responsibility of rejecting the Gospel remains even when its final saving effect is not granted to all.', ['John Calvin','Jonathan Edwards','Westminster Assembly'])
    ],clashes:['Wounded freedom versus total inability.','Synergy versus monergistic conversion.','Resistible grace versus effectual calling.','Whether divine causality and free creaturely action are compatible.'],history:[H('Pelagius and Augustine','5th century','The Pelagian controversy makes grace and free will a central doctrinal question.','Augustine insists that even the beginning of faith requires grace.'),H('529','Second Council of Orange','The council emphasizes prevenient grace and rejects Pelagian accounts of autonomous conversion.','It becomes an important Western witness against self-sufficient human salvation.'),H('13th century','Thomas Aquinas','Aquinas develops a sophisticated account of divine causality and free choice.','God’s causality and creaturely freedom are not competing explanations.'),H('1525','Luther, Bondage of the Will','Luther argues that the fallen will cannot generate saving faith.','The Reformation debate turns on the meaning of freedom in relation to grace.'),H('16th century','Calvin and Reformed confessions','Regeneration and effectual calling become central to Reformed soteriology.','Freedom is understood as restored by grace rather than as autonomous neutrality.'),H('17th century','Arminian controversy','The Remonstrants emphasize conditional election and resistible grace.','The debate exposes different ways of coordinating universal grace and election.')],sources:[S('Augustine','On Grace and Free Will','https://www.newadvent.org/fathers/1510.htm','Primary'),S('Augustine','On the Predestination of the Saints','https://www.newadvent.org/fathers/1512.htm','Primary'),S('Second Council of Orange','Canons','https://www.newadvent.org/fathers/1501.htm','Primary council'),S('Thomas Aquinas','Summa I-II, qq.109–114','texts/summa.html?part=prima-sec&q=109&a=1','Primary'),S('Martin Luther','Bondage of the Will','https://www.ccel.org/ccel/luther/bondage','Primary'),S('John Calvin','Institutes II.2','https://www.ccel.org/ccel/calvin/institutes.ii.ii.html','Primary'),S('Westminster Confession','Chapter 9','https://wts.edu/wcf','Confession'),S('John Cassian','Conferences','https://www.newadvent.org/fathers/3501.htm','Primary Eastern witness')]},

    'original-sin':{domain:'Anthropology',title:'Original Sin',centralQuestion:'What exactly has happened to humanity through Adam’s Fall?',definition:'Original sin names the universal fallen condition into which humanity is born. Christian traditions agree that Adam’s sin has consequences for every human being and that Christ is necessary for restoration. They differ over inherited guilt, corruption, mortality, concupiscence, the freedom of the will, and what baptism removes.',lead:'Romans 5, 1 Corinthians 15, Genesis 3, Augustine’s anti-Pelagian writings, Eastern patristic anthropology, Aquinas, Luther, Calvin, and Trent form the major historical conversation. The key distinction is between saying that humanity inherits Adam’s personal guilt as guilt and saying that humanity inherits a corrupted, mortal condition in which sin becomes universal.',questions:['Do humans inherit guilt or only corruption?','What does Adam’s sin do to human nature?','What is concupiscence?','Why do infants need baptism?','How does Christ as New Adam reverse Adam’s fall?'],traditions:[
      T('catholic','Catholic','Original sin is an inherited deprivation of original holiness and justice, not the personal guilt of Adam’s descendants.',[
        'Catholic theology teaches that Adam’s first sin damaged the human condition. Descendants inherit a state lacking original holiness, with wounded intellect and will and a tendency toward disordered desire. This condition is called original sin, but it is not a personal act committed by the infant.',
        'Baptism removes original sin and restores sanctifying grace, yet concupiscence remains as an inclination to sin. It is not itself personal sin unless consented to.',
        'Mary’s Immaculate Conception is a special grace preserving her from original sin from the first moment of her conception. Christ, the New Adam, restores what Adam lost and elevates humanity beyond the original state into supernatural communion.'
      ],'The Catholic formulation protects both universality and personal responsibility: everyone needs redemption, but guilt in the strict personal sense is not transferred as though an infant had personally committed Adam’s act.', 'Reformed critics argue that Catholic language of deprivation understates inherited guilt; Orthodox critics object to importing too much Augustinian guilt-language into the Eastern tradition.', 'Catholic theology distinguishes inherited condition from personal culpability and therefore can affirm universal need for grace without blaming infants for Adam’s act.', ['Augustine','Thomas Aquinas','Council of Trent','Catechism of the Catholic Church']),
      T('orthodox','Eastern Orthodox','Humanity inherits mortality, corruption, and a disordered condition from Adam, but not Adam’s personal guilt.',[
        'Eastern theology commonly speaks of ancestral sin rather than inherited guilt. Adam’s fall introduces death and corruption, and human beings are born into an environment and condition in which sin becomes pervasive.',
        'The image of God is damaged but not erased. Humanity remains capable of responding to God, though salvation requires divine grace and healing. The problem is therefore medicinal and ontological as well as moral.',
        'Baptism unites the person to Christ’s death and resurrection and begins the healing process. Theosis is the positive end: not merely restoration to Eden but participation in divine life.'
      ],'The Orthodox account seeks to preserve the goodness of created human nature. Sin is devastating, but it is not a substance added to nature; corruption and death are parasitic distortions.', 'Western critics argue that if inherited guilt is denied, the universality and seriousness of Adam’s sin can appear weakened.', 'Orthodox theology answers that death itself is universal and that every person personally confirms Adam’s condition through actual sin. Christ heals the condition without treating infants as personally culpable for Adam.', ['Irenaeus','Gregory of Nyssa','John Chrysostom','John of Damascus']),
      T('lutheran','Lutheran','Original sin is a deep corruption of human nature that leaves humanity unable to produce true love of God apart from grace.',[
        'Lutheran confessions speak strongly of inherited sin. Humanity is born without original righteousness and with a corrupted nature inclined away from God. This affects the whole person rather than only isolated acts.',
        'Baptism truly gives forgiveness and new birth, but the old Adam remains. The believer lives in the tension of being justified while still struggling with sin.',
        'Lutheran theology therefore takes both universality and personal responsibility seriously. Sin is not merely imitation of Adam; it is a condition that produces actual transgression.'
      ],'The doctrine explains why grace must be radical. If the problem is merely bad example or moral weakness, Christ becomes a teacher rather than the Redeemer who gives a new status and life.', 'Catholic and Orthodox theology can object that strong inherited-guilt formulations risk confusing Adam’s act with the personal guilt of descendants.', 'Lutheran theology distinguishes inherited corruption from individual acts while retaining strong language about humanity’s lack of original righteousness.', ['Martin Luther','Augsburg Confession','Formula of Concord']),
      T('reformed','Reformed','Adam’s covenant headship means his fall brings guilt and corruption to his descendants; humanity is radically unable to restore itself.',[
        'Reformed theology develops a strong doctrine of federal headship: Adam represents humanity in the covenant of works, so his disobedience has consequences for those he represents. Romans 5 is read alongside the parallel between Adam and Christ.',
        'The fall produces both imputed guilt and inherited corruption. Humanity is therefore guilty and spiritually unable apart from grace. Total depravity does not mean every person is maximally evil; it means sin reaches every faculty.',
        'Christ is the second Adam. His obedience is the ground of the believer’s justification just as Adam’s disobedience is the source of condemnation. The parallel structures the whole Reformed account of salvation.'
      ],'The federal reading gives Romans 5 a symmetrical logic: Adam represents humanity in condemnation; Christ represents His people in justification.', 'Catholic and Orthodox critics object that imputing Adam’s guilt before personal action seems contrary to individual moral responsibility.', 'Reformed theology answers that representative headship is not an arbitrary fiction: human life is inherently covenantal and corporate. The same structure that condemns in Adam grounds salvation in Christ.', ['John Calvin','Francis Turretin','Westminster Assembly'])
    ],clashes:['Inherited guilt versus inherited mortality/corruption.','Whether original sin is a deprivation, corruption, legal guilt, or all three.','The effect of the Fall on freedom.','What baptism removes immediately and what remains as concupiscence or corruption.'],history:[H('c. 180','Irenaeus','Adam–Christ recapitulation becomes a major patristic framework.','Humanity’s story is reversed and fulfilled in the obedient Christ.'),H('c. 400','Augustine','Original sin becomes tightly linked to inherited corruption, grace, and baptism.','Augustine’s anti-Pelagian writings become foundational in the Latin West.'),H('529','Second Council of Orange','The Western Church rejects Pelagian accounts of human ability.','The council emphasizes grace in the fallen condition.'),H('13th century','Aquinas','Original sin is described as deprivation of original justice and disorder in the powers of the soul.','Aquinas integrates Augustinian anthropology with scholastic analysis.'),H('16th century','Luther and Calvin','Reformation theology develops strong accounts of inherited sin and inability.','Adam’s fall becomes closely connected to justification and election.'),H('1546','Council of Trent','Trent defines original sin and its removal through baptism.','It rejects both Pelagianism and Protestant formulations it sees as excessive.')],sources:[S('Augustine','On Nature and Grace','https://www.newadvent.org/fathers/1507.htm','Primary'),S('Irenaeus','Against Heresies III.18','https://www.newadvent.org/fathers/0103318.htm','Primary'),S('John Chrysostom','Homilies on Romans','https://www.newadvent.org/fathers/2102.htm','Primary'),S('Thomas Aquinas','Summa I-II, qq.81–85','texts/summa.html?part=prima-sec&q=81&a=1','Primary'),S('Council of Trent','Decree on Original Sin','https://www.newadvent.org/cathen/15030c.htm','Primary council'),S('Augsburg Confession','Article II','https://bookofconcord.org/augsburg-confession/chief_articles/article_ii/','Confession'),S('Westminster Confession','Chapter 6','https://wts.edu/wcf','Confession'),S('Catechism of the Catholic Church','§§385–421','https://www.vatican.va/content/catechism/en/part_one/section_two/chapter_one/article_1/ii_the_fall.html','Secondary synthesis')]},

    baptism:{domain:'Sacraments',title:'Baptism',centralQuestion:'What does it mean to be baptized into Christ?',definition:'Baptism is the Christian initiation into Christ through water and the Triune name. It is associated in the New Testament with repentance, forgiveness, regeneration, union with Christ’s death and resurrection, incorporation into the Church, and the gift of the Spirit. The traditions differ over the relation of baptism to justification, regeneration, faith, covenant, and the timing of baptism.',lead:'Baptism is one of the few practices universally shared across historic Christianity, yet it contains major theological fault lines. Catholic and Orthodox theology treats baptism as a true sacramental rebirth; Lutheran theology treats it as a means of grace that genuinely gives forgiveness and new birth; Reformed theology calls it a sign and seal of the covenant while refusing to make its efficacy automatic; most Baptist and free-church traditions distinguish baptism from regeneration and practice believer’s baptism.',questions:['Does baptism itself give regeneration and forgiveness?','Should infants be baptized?','Is baptism necessary for salvation?','What is the relation between baptism and faith?','What does baptism signify about union with Christ?'],traditions:[
      T('catholic','Catholic','Baptism is the sacrament of regeneration and forgiveness that incorporates the person into Christ and His Church.',[
        'Catholic theology takes seriously the New Testament association of baptism with new birth, forgiveness, death and resurrection with Christ, and incorporation into the Church. Baptism removes original and personal sin, gives sanctifying grace, and marks the Christian with an indelible sacramental character.',
        'Infant baptism follows the Church’s conviction that salvation is gift rather than a reward for intellectual maturity. The faith of the Church surrounds the child, who later ratifies baptism through personal faith and Christian life.',
        'Because baptism gives a once-for-all incorporation into Christ, it is not repeated. A valid Trinitarian baptism remains baptism even if the person later falls into grave sin; reconciliation after the Fall is handled through penance.'
      ],'The Catholic case combines Scripture, early Church practice, and sacramental anthropology: if baptism truly unites a person to Christ, delaying it until autonomous decision is not necessary.', 'Baptist and some Reformed critics argue that baptism should follow conscious profession and that infant baptism obscures the biblical pattern of believing and then being baptized.', 'Catholic theology answers that Scripture contains household baptisms, covenant continuity, and a theology of grace that does not make infant incapacity an obstacle to divine action.', ['Ambrose','Augustine','Thomas Aquinas','Council of Trent']),
      T('orthodox','Eastern Orthodox','Baptism is death and rebirth in Christ, ordinarily joined immediately to chrismation and Eucharistic communion.',[
        'Orthodox baptism is deeply Paschal. Immersion signifies burial and rising with Christ; the newly baptized is incorporated into the Church and ordinarily receives chrismation and Eucharist as part of the unified rite of initiation.',
        'Infant baptism is normal because salvation is incorporation into Christ and the Church, not merely the public certification of an already autonomous decision. Personal faith and ascetic growth follow as the child matures.',
        'The baptismal life is a life of repentance and theosis. The sacrament is not a magical endpoint but the beginning of participation in Christ.'
      ],'The Orthodox emphasis on immersion, chrismation, and immediate Eucharist reveals baptism as entry into the entire sacramental life rather than an isolated rite.', 'Some Protestants object that infant baptism lacks personal profession of faith.', 'Orthodox theology answers that the Church baptizes into a communal life of faith and that personal assent develops within that life.', ['Cyril of Jerusalem','John Chrysostom','John of Damascus']),
      T('lutheran','Lutheran','Baptism is a means of grace in which God gives forgiveness, life, and salvation through water joined to His Word.',[
        'Lutheran theology rejects the idea that baptism is merely a human testimony. Because Christ commands baptism and attaches promises to it, God acts through the sacrament. Faith receives the promise, but the sacrament does not become empty when the recipient is an infant.',
        'Infant baptism is defended by the universality of grace and the Church’s responsibility to bring children to Christ. The baptized person is called to live continually from the promise received.',
        'Baptism remains central to Lutheran assurance: when doubt arises, the Christian can look back to God’s objective promise rather than measure the intensity of personal experience.'
      ],'The Lutheran argument is sacramental and evangelical: God’s promise is stronger than the believer’s fluctuating psychological certainty.', 'Reformed and Baptist critics object that baptismal efficacy can sound automatic.', 'Lutheran theology distinguishes the sacramental promise from mechanical magic. Faith is not a work that activates God; unbelief can reject the gift even though the promise is genuinely given.', ['Martin Luther','Augsburg Confession','Small Catechism']),
      T('reformed','Reformed','Baptism is a covenant sign and seal of union with Christ, regeneration, cleansing, and incorporation into the visible Church, whose efficacy depends on God’s Spirit rather than the external rite alone.',[
        'Reformed theology strongly affirms baptism as more than a human symbol. The Westminster Confession calls it a sign and seal of the covenant of grace and associates it with union with Christ, regeneration, and remission of sins.',
        'Yet baptism’s efficacy is not tied mechanically to the moment of administration. The Spirit applies the grace signified according to God’s purpose. This allows Reformed theology to maintain both sacramental seriousness and a distinction between sign and the inward work of grace.',
        'Infant baptism follows covenant continuity: children of believers belong to the visible covenant community just as infants belonged to Israel under circumcision.'
      ],'The Reformed position aims to preserve the biblical covenant structure without making the external rite itself determinative of regeneration.', 'Baptists argue that the New Testament pattern connects baptism with conscious faith and that covenant membership should follow personal profession.', 'Reformed theology answers that the covenant sign can be received by children and that regeneration is ultimately God’s sovereign work, not a function of age or ritual timing.', ['John Calvin','Westminster Assembly','Huldrych Zwingli'])
    ],clashes:['Sacramental regeneration versus baptism as sign and seal.','Infant baptism versus believer’s baptism.','Whether baptismal grace is tied to the moment of administration.','The relation between baptism, faith, and covenant membership.'],history:[H('c. 100','Didache','Early Christian teaching describes baptismal practice and preparation.','It witnesses to baptism as a structured ecclesial practice.'),H('c. 180','Irenaeus','Baptism is associated with regeneration and incorporation into Christ.','The sacramental and incarnational pattern is already visible.'),H('c. 350','Cyril of Jerusalem','Catecheses interpret baptism as death and resurrection with Christ.','The liturgical theology of initiation becomes explicit.'),H('4th–5th centuries','Infant baptism becomes widespread','Augustine and other Fathers treat baptism as necessary for the Church’s initiation of children.','The practice becomes normal in catholic Christianity.'),H('16th century','Reformation baptismal debates','Lutherans and Reformed retain infant baptism; Anabaptists reject it.','The disagreement reveals different accounts of Church and covenant.'),H('1640s','Westminster Confession','Reformed confessional theology formalizes baptism as covenant sign and seal.','The sacramental language is retained without Catholic sacramental causality.')],sources:[S('Didache','Chapter 7','https://www.newadvent.org/fathers/0714.htm','Primary'),S('Cyril of Jerusalem','Catechetical Lectures','https://www.newadvent.org/fathers/3101.htm','Primary'),S('Augustine','On Baptism','https://www.newadvent.org/fathers/1408.htm','Primary'),S('Thomas Aquinas','Summa III, qq.66–69','texts/summa.html?part=tertia&q=66&a=1','Primary'),S('Augsburg Confession','Article IX','https://bookofconcord.org/augsburg-confession/chief_articles/article_ix/','Confession'),S('Westminster Confession','Chapter 28','https://wts.edu/wcf','Confession'),S('Orthodox Church in America','The Orthodox Faith: Baptism','https://www.oca.org/orthodoxy/the-orthodox-faith/doctrine-scripture/the-symbol-of-faith/sacraments','Secondary traditional synthesis'),S('Catechism of the Catholic Church','§§1210–1284','https://www.vatican.va/content/catechism/en/part_two/section_two/chapter_one/article_1.html','Secondary synthesis')]},

    penance:{domain:'Sacraments & Repentance',title:'Penance',centralQuestion:'How does the baptized Christian return to communion after falling into sin?',definition:'Penance is the Church’s sacramental and ascetical response to post-baptismal sin: repentance, confession, forgiveness, reconciliation, and renewed life. Catholicism treats sacramental confession as a distinct sacrament; Orthodoxy practices sacramental confession and absolution within spiritual fatherhood; Lutheranism retains private confession and absolution while rejecting a sacramental system identical to Catholicism; Reformed traditions emphasize repentance, discipline, and pastoral absolution without sacramental confession as a divinely instituted rite.',lead:'The underlying question is universal: what happens when someone who has entered the Christian life sins? The early Church’s penitential discipline, the power of the keys, and Christ’s words about forgiving and retaining sins form the common biblical horizon. The traditions differ over whether confession to a priest is necessary by divine institution, how absolution works, and whether penance is properly sacramental, pastoral, or primarily ecclesial discipline.',questions:['Did Christ institute a sacrament of reconciliation after baptism?','Must sins be confessed to a minister?','What is absolution?','What is the relation between repentance and forgiveness?','Can a Christian have assurance of forgiveness through an objective absolution?'],traditions:[
      T('catholic','Catholic','Penance is the sacrament by which the baptized are reconciled to God and the Church after sin through contrition, confession, absolution, and satisfaction.',[
        'Catholic theology reads Christ’s gift of the keys—especially John 20:21–23—as establishing a ministry in which the Church truly forgives sins in Christ’s name. The penitent confesses serious sins, expresses contrition, receives absolution, and performs a penance ordered toward healing and restoration.',
        'Absolution is not merely advice. The priest acts sacramentally in persona Christi. The sacrament restores sanctifying grace when lost through mortal sin and reconciles the sinner to ecclesial communion.',
        'Penance is sometimes called a “laborious baptism” because it restores what baptism first gave, but it does not repeat baptism. The sacrament also includes the medicinal dimension of conversion: forgiveness is inseparable from a renewed life.'
      ],'The Catholic argument takes the Church’s authority to forgive sins as a concrete continuation of Christ’s ministry. If Christ entrusted the keys to the apostles, the Church can minister forgiveness rather than merely announce that God forgives.', 'Protestant critics argue that Christ’s finished work means no priestly sacrament is needed for forgiveness and that confession can obscure justification by faith.', 'Catholic theology responds that sacramental confession does not compete with Christ’s Cross; it applies Christ’s mercy through the ministry He instituted. Absolution is itself grace.', ['John Chrysostom','Thomas Aquinas','Council of Trent']),
      T('orthodox','Eastern Orthodox','Confession and absolution are sacramental mysteries of repentance in which the sinner is reconciled to God within the Church.',[
        'Orthodox confession is ordinarily made before a priest who serves as witness and spiritual guide. The priest’s role is therapeutic and ecclesial: he hears the confession, offers counsel, and pronounces absolution in the Church’s prayer.',
        'The Orthodox tradition often avoids reducing forgiveness to a juridical transaction. Sin is disease and rupture; repentance is return to communion and healing. The priest is not a rival to God but a servant of divine mercy.',
        'Penitential practice includes prayer, fasting, restitution, and ascetic discipline. The sacramental moment belongs to a larger life of conversion.'
      ],'The Orthodox account preserves sacramental absolution while framing it through healing and spiritual fatherhood rather than primarily through legal satisfaction.', 'Some Protestant traditions argue that confession to a priest is unnecessary because every Christian has direct access to God through Christ.', 'Orthodox theology answers that direct access to God does not eliminate the visible ministry of reconciliation. Christ’s Church is embodied, and repentance is ordinarily ecclesial.', ['John Chrysostom','Basil the Great','John Climacus']),
      T('lutheran','Lutheran','Private confession and absolution remain valuable means by which Christ’s forgiveness is personally declared to the penitent.',[
        'Luther strongly criticized abuses surrounding medieval penance but did not simply abolish confession. The Small Catechism teaches private confession and absolution as a precious practice, especially for troubled consciences.',
        'The minister does not forgive by personal power. Absolution is Christ’s Word spoken to the sinner. Its pastoral force lies precisely in its objectivity: the penitent hears forgiveness rather than merely inferring it from an internal feeling.',
        'Lutheran theology generally rejects the Catholic classification of penance as a sacrament requiring satisfaction in the same sense, but it retains a robust doctrine of absolution.'
      ],'The Lutheran concern is the terrified conscience. The sinner needs a concrete Gospel promise, not an endless examination of whether repentance is sufficiently sincere.', 'Reformed traditions may regard private absolution as unnecessary, while Catholic theology argues that Lutheranism retains much of the sacramental substance without the full doctrine of priestly sacramental power.', 'Lutherans answer that the decisive thing is Christ’s promise. The minister is the instrument through which that promise is delivered.', ['Martin Luther','Small Catechism','Augsburg Confession']),
      T('reformed','Reformed','Repentance is necessary throughout the Christian life; ministers announce forgiveness and exercise discipline, but private sacramental confession is not ordinarily treated as a divinely instituted sacrament.',[
        'Reformed theology takes repentance seriously as a lifelong turning from sin. The Church has authority to preach forgiveness, exercise discipline, and restore the repentant. Yet justification remains grounded in Christ and received by faith, not in sacramental satisfaction.',
        'Public and pastoral confession can be valuable, especially when sin harms another person or the Church. Some Reformed traditions retain forms of corporate confession and absolution in worship.',
        'Church discipline protects the holiness of the visible Church and seeks restoration rather than mere punishment.'
      ],'The Reformed argument protects direct access to Christ while preserving ecclesial ministry. Ministers declare the Gospel; they do not become a second source of atonement.', 'Catholic and Orthodox theology argues that this weakens the concrete gift of the keys and leaves the sinner without a distinct sacramental encounter with forgiveness.', 'Reformed theology answers that the promise of the Gospel is no less objective when preached rather than sacramentally absolved, and that Christ’s once-for-all mediation does not require priestly sacramental mediation of every grave sin.', ['John Calvin','Westminster Assembly','Heidelberg Catechism'])
    ],clashes:['Sacramental absolution versus proclamation of forgiveness.','Priestly ministry of the keys versus pastoral ministry of the Word.','Satisfaction and penance as part of sacramental reconciliation versus repentance as fruit of faith.','The role of confession in assurance.'],history:[H('c. 100–200','Early penitential practice','The Church develops public and private forms of repentance and reconciliation.','The severity and frequency of post-baptismal penance develop over time.'),H('c. 250','Cyprian','The Church’s authority to reconcile penitents becomes a major issue.','The ministry of the bishop and unity of the Church are connected to reconciliation.'),H('4th–5th centuries','Private confession expands','Pastoral practice develops forms of repeated confession and spiritual direction.','The sacramental pattern becomes more stable in East and West.'),H('1215','Fourth Lateran Council','Annual confession becomes a universal Latin requirement.','The council formalizes penitential discipline in the medieval West.'),H('16th century','Reformation','Luther preserves absolution while rejecting abuses; Reformed churches restructure discipline.','Confession becomes a major test case for competing views of ministry and justification.'),H('1547','Council of Trent','Trent defines confession, contrition, satisfaction, and priestly absolution.','Catholic sacramental theology receives a precise conciliar formulation.')],sources:[S('Tertullian','On Repentance','https://www.newadvent.org/fathers/0312.htm','Primary'),S('Cyprian','On the Lapsed','https://www.newadvent.org/fathers/0506.htm','Primary'),S('John Chrysostom','On the Priesthood','https://www.newadvent.org/fathers/1922.htm','Primary'),S('Thomas Aquinas','Summa III, qq.84–90','texts/summa.html?part=tertia&q=84&a=1','Primary'),S('Martin Luther','Small Catechism: Confession','https://bookofconcord.org/small-catechism/','Primary confession'),S('Council of Trent','Session XIV','https://www.newadvent.org/cathen/15030c.htm','Primary council'),S('Westminster Confession','Chapter 15','https://wts.edu/wcf','Confession'),S('Catechism of the Catholic Church','§§1422–1498','https://www.vatican.va/content/catechism/en/part_two/section_two/chapter_two/article_4.html','Secondary synthesis')]},

    'scripture-tradition':{domain:'Revelation & Authority',title:'Scripture & Tradition',centralQuestion:'How does the apostolic faith remain authoritative across generations?',definition:'Scripture and Tradition concern the transmission, preservation, interpretation, and authority of the apostolic faith. Every Christian tradition receives a historical tradition; the disagreement concerns whether Scripture is the sole infallible norm, how Tradition functions alongside Scripture, and who has authority to settle disputes about interpretation.',lead:'The early Church receives apostolic writings within a living ecclesial tradition of preaching, worship, baptismal confession, episcopal succession, and canon. Catholic and Orthodox theology therefore speaks of Scripture within Holy Tradition, while classical Protestantism insists on Scripture as the supreme or sole infallible norm while retaining subordinate creeds and traditions. The debate is ultimately about revelation, authority, canon, and interpretation.',questions:['Is Scripture the only infallible rule?','What is Holy Tradition?','How was the biblical canon recognized?','Who can settle doctrinal disputes?','Can tradition ever bind conscience?'],traditions:[
      T('catholic','Catholic','Sacred Scripture and Sacred Tradition form one sacred deposit of the Word of God entrusted to the Church.',[
        'Catholic theology does not oppose Scripture to Tradition. Scripture is the inspired written Word; Tradition is the living transmission of the apostolic faith. Both flow from the same divine source and together constitute the deposit of faith.',
        'The Magisterium is not above the Word of God. Its task is to serve it by authentically interpreting the deposit entrusted to the Church. The canon itself was received within the Church’s historical life.',
        'This does not mean every custom is infallible. Catholic theology distinguishes apostolic Tradition from mutable disciplinary traditions.'
      ],'The Catholic argument emphasizes the historical impossibility of treating the Bible as a self-authenticating book detached from the Church that transmitted and canonized it.', 'Protestants argue that this creates a circular authority structure: the Church authenticates the canon and then claims authority to interpret it.', 'Catholic theology answers that recognition is not creation. The Church does not make Scripture inspired; she receives and identifies the apostolic books within the life of the apostolic community.', ['Irenaeus','Vincent of Lérins','John Henry Newman','Vatican II']),
      T('orthodox','Eastern Orthodox','Scripture is the heart of Holy Tradition, interpreted and lived within the worship and conciliar life of the Church.',[
        'Orthodoxy strongly rejects the idea that Tradition is merely a collection of later human additions. Scripture itself is part of Holy Tradition: the Church receives, reads, chants, preaches, and interprets it within the liturgical and conciliar life of the Body of Christ.',
        'The Ecumenical Councils do not stand above Scripture but witness to its faithful interpretation. The Fathers are authoritative because they participate in the Church’s common confession rather than because every patristic sentence is infallible.',
        'The liturgy is a living theological text. What the Church prays reveals how the Church understands what she believes.'
      ],'The Orthodox argument is fundamentally ecclesial: Scripture is not a detached authority but the written heart of the Church’s living apostolic memory.', 'Protestants object that this can make Tradition difficult to distinguish from later development and can weaken Scripture’s corrective authority.', 'Orthodoxy responds that Scripture itself emerged within the apostolic Church and that a purely individual interpretive method is historically foreign to Christianity.', ['Irenaeus','Athanasius','John of Damascus','Vladimir Lossky']),
      T('lutheran','Lutheran','Holy Scripture is the supreme norm of doctrine; creeds and traditions are authoritative insofar as they faithfully confess Scripture.',[
        'Lutheran theology strongly distinguishes Scripture as the norma normans—the norm that norms—from ecclesial traditions that are themselves normed by Scripture. The Lutheran confessions claim authority because they summarize Scripture faithfully.',
        'The Reformation did not reject all tradition. It appealed constantly to the Fathers and ancient Creeds while criticizing medieval doctrines judged to lack sufficient biblical foundation.',
        'The authority of Scripture is linked to Christ and the Gospel: the Bible is not an autonomous rulebook but the authoritative apostolic witness to God’s saving work.'
      ],'The Lutheran argument is reforming rather than anti-traditional: traditions may be retained, but they cannot bind conscience against the clear Word of God.', 'Catholic and Orthodox critics argue that the canon and interpretive tradition make some form of ecclesial authority unavoidable.', 'Lutherans answer that historical recognition does not make the Church the source of Scripture’s authority. The Church is a servant and witness to the apostolic Word.', ['Martin Luther','Philip Melanchthon','Book of Concord']),
      T('reformed','Reformed','Scripture is the only infallible rule of faith and life, while creeds and councils have subordinate authority.',[
        'The Reformed doctrine of sola Scriptura does not mean “no tradition.” Calvin, the Reformed confessions, and the Puritans rely heavily on the Fathers and ancient Creeds. The claim is that Scripture alone is infallible and therefore has the final right to correct every subordinate authority.',
        'The Church is necessary for teaching and interpretation, but no minister, council, or confession can become an independent source of revelation equal to Scripture.',
        'This doctrine also protects the conscience: Christians are bound by God’s Word rather than by later ecclesiastical commands that cannot be demonstrated from Scripture.'
      ],'The Reformed argument seeks a final court of appeal that cannot itself be overturned by another human authority.', 'Catholic and Orthodox critics argue that competing Protestant interpretations demonstrate that Scripture without an authoritative interpretive communion does not settle disputes in practice.', 'Reformed theology answers that interpretive disagreement does not prove the absence of objective truth. Scripture remains the standard even when readers disagree about it.', ['John Calvin','Francis Turretin','Westminster Assembly'])
    ],clashes:['Scripture alone as sole infallible norm versus Scripture within Holy Tradition.','The authority of councils and Fathers.','How the biblical canon is recognized.','Whether the Church possesses a charism of authoritative interpretation.'],history:[H('c. 180','Irenaeus','Scripture, apostolic succession, and the rule of faith operate together against Gnosticism.','The early Church does not separate written Scripture from ecclesial tradition.'),H('367','Athanasius, Festal Letter','Athanasius gives the familiar 27-book New Testament list.','The canon is increasingly stabilized through ecclesial reception.'),H('787','Second Council of Nicaea','The council appeals to Scripture and patristic tradition in defining icon veneration.','Conciliar authority is explicitly exercised within received Tradition.'),H('16th century','Reformation','Sola Scriptura becomes a defining Protestant principle.','The authority of councils, canon, and tradition is renegotiated.'),H('1546','Council of Trent','Trent defines the Catholic relationship between Scripture and unwritten traditions.','The Catholic response to the Reformation is codified.'),H('1860s–1960s','Modern Catholic–Orthodox–Protestant reflection','The traditions develop more nuanced accounts of Scripture, tradition, and development.','Modern ecumenical theology often identifies greater overlap than polemical formulas suggest.')],sources:[S('Irenaeus','Against Heresies III.3','https://www.newadvent.org/fathers/0103303.htm','Primary'),S('Athanasius','Festal Letter 39','https://www.newadvent.org/fathers/2806039.htm','Primary'),S('Vincent of Lérins','Commonitorium','https://www.newadvent.org/fathers/3506.htm','Primary'),S('John of Damascus','On Holy Images','https://www.newadvent.org/fathers/3309.htm','Primary'),S('Martin Luther','Prefaces and Scripture writings','https://www.gutenberg.org/ebooks/31617','Primary/free edition'),S('John Calvin','Institutes I.6–9','https://www.ccel.org/ccel/calvin/institutes.i.vi.html','Primary'),S('Vatican II','Dei Verbum','https://www.vatican.va/archive/hist_councils/ii_vatican_council/documents/vat-ii_const_19651118_dei-verbum_en.html','Primary council'),S('Westminster Confession','Chapter 1','https://wts.edu/wcf','Confession')]},

    predestination:{domain:'Providence & Salvation',title:'Predestination',centralQuestion:'How does God’s eternal purpose relate to the salvation and freedom of His creatures?',definition:'Predestination concerns God’s eternal purpose concerning salvation. All classical Christian traditions affirm divine providence, but they differ over unconditional election, foreknowledge, reprobation, human freedom, the extent of saving grace, and the degree to which theology should describe God’s hidden decree.',lead:'Paul, Augustine, Aquinas, the Council of Orange, Luther, Calvin, the Synod of Dort, and later Catholic and Orthodox theologians form the central historical conversation. The deepest question is not whether God knows the future, but whether His saving purpose is the ultimate cause of faith and perseverance, how this relates to freedom, and what can responsibly be said about those who are not saved.',questions:['Is election unconditional?','Is election based on foreseen faith?','Does God positively predestine anyone to damnation?','Can grace be resisted?','How can predestination coexist with genuine freedom?'],traditions:[
      T('catholic','Catholic','God predestines the elect to salvation by grace while preserving real freedom and refusing to make God the author of sin.',[
        'Catholic theology strongly affirms predestination but treats it within divine providence. Aquinas teaches that election has its cause in God, not in foreseen merit. Yet Catholic theology refuses to make God’s decree a cause of sin or to reduce human freedom to determinism.',
        'The Church does not define one complete model for the relation between predestination, grace, and foreknowledge. Thomist and Molinist schools offer different accounts of how God’s knowledge and providence relate to free acts.',
        'The pastoral emphasis is that salvation is grace and that no one should despair by attempting to discover a hidden decree. The revealed will of God is repentance and faith in Christ.'
      ],'The Catholic position preserves both the priority of grace and the genuine moral reality of human choices. The mystery is not solved by reducing one side to the other.', 'Reformed theology argues that unconditional election should be stated more explicitly if grace is truly decisive. Some Thomists agree with strong unconditional language, while Molinists stress middle knowledge and libertarian freedom.', 'Catholic theology permits legitimate schools within defined doctrinal boundaries and rejects the claim that every theological mystery must be reduced to one mechanical model.', ['Augustine','Thomas Aquinas','Francisco Suárez','Council of Trent']),
      T('orthodox','Eastern Orthodox','God foreknows and calls His creatures without reducing salvation to a deterministic decree; synergy remains real.',[
        'Orthodox theology emphasizes God’s universal goodness and the reality of human response. Predestination is generally not treated through the Reformed system of unconditional election and symmetrical reprobation.',
        'Foreknowledge does not mean causation. God knows free actions without compelling them. Salvation is therefore a mystery of divine initiative and human cooperation rather than a closed chain of decrees.',
        'The positive content of predestination is conformity to Christ and participation in divine life. Orthodox theology is wary of speculation about hidden decrees that can distract from repentance and prayer.'
      ],'The Orthodox concern is pastoral and metaphysical: the God who calls all to salvation cannot be portrayed as the efficient cause of the damnation of those He created for communion.', 'Reformed theology argues that this leaves God’s saving purpose dependent on a mutable human response.', 'Orthodoxy answers that grace is not weakened by freedom. A freely given response is itself possible only because God first acts.', ['John Chrysostom','John of Damascus','Maximus the Confessor']),
      T('lutheran','Lutheran','Election to salvation is confessed as God’s gracious choice in Christ, while speculation about reprobation is restrained.',[
        'The Lutheran confessions emphasize election as comfort: believers should look to Christ and the Gospel rather than speculate about a hidden decree. God’s grace is the source of faith and salvation.',
        'Lutheran theology rejects the idea that those who are damned were created or predestined to sin by a symmetrical divine decree. The cause of salvation is grace; the cause of damnation is sin and unbelief.',
        'This asymmetry is deliberately maintained. Theology is directed toward the revealed promise rather than toward constructing a comprehensive account of God’s secret counsel.'
      ],'The Lutheran approach seeks to protect assurance without turning predestination into speculation. Election is Gospel when it directs the sinner to Christ.', 'Reformed theology argues that this does not fully explain why some receive effectual grace and others do not.', 'Lutheran theology accepts the mystery rather than filling it with a decree that it believes Scripture does not reveal for pastoral speculation.', ['Martin Luther','Formula of Concord','Martin Chemnitz']),
      T('reformed','Reformed','God unconditionally elects sinners to salvation, effectually calls them, and preserves them; Reformed confessions also teach a doctrine of reprobation while denying that God is the author of sin.',[
        'Reformed theology places predestination within the sovereignty of God. Election is not grounded in foreseen merit or faith; faith itself is the fruit of election and regeneration.',
        'Effectual calling ensures that those whom God intends to save are brought to faith. Perseverance follows from the same divine purpose. Reformed theology therefore sees a coherent chain from election to glorification.',
        'Classical confessions also speak of reprobation, though formulations vary. God’s decree does not make Him the author of sin; the condemned remain guilty for their own unbelief and sin.'
      ],'If grace is finally decisive, Reformed theology argues, election must be decisive as well. Otherwise the ultimate differentiating cause between the saved and lost is located in the human response.', 'Catholic, Orthodox, Lutheran, and Arminian critics argue that the doctrine threatens universal grace and creates moral difficulties concerning reprobation.', 'Reformed theology distinguishes God’s decree from the sinful acts of creatures and insists that the universal Gospel offer remains sincere even though effectual saving grace is particular.', ['John Calvin','Theodore Beza','Synod of Dort','Westminster Assembly'])
    ],clashes:['Unconditional election versus election conditioned on foreknown faith.','Single predestination versus explicit reprobation.','Effectual versus resistible grace.','How divine foreknowledge relates to genuine human freedom.'],history:[H('c. 400','Augustine','Grace and predestination become central in Augustine’s mature anti-Pelagian theology.','The priority of grace becomes a defining Western theme.'),H('529','Second Council of Orange','The council rejects Pelagianism and emphasizes prevenient grace.','It does not adopt the later Reformed system of double predestination.'),H('13th century','Aquinas','Predestination is treated as an aspect of divine providence.','Aquinas places election within God’s universal causality.'),H('1520s','Luther','Predestination and the hidden/revealed God become important themes.','Luther warns against seeking assurance in God’s secret counsel rather than Christ.'),H('1530s–1560s','Calvin','Predestination becomes a central organizing doctrine of Reformed theology.','Election is closely connected to union with Christ and assurance.'),H('1618–1619','Synod of Dort','Reformed churches respond to the Remonstrants.','Unconditional election and effectual grace receive confessional definition.')],sources:[S('Augustine','On the Predestination of the Saints','https://www.newadvent.org/fathers/1512.htm','Primary'),S('Thomas Aquinas','Summa I, q.23','texts/summa.html?part=prima&q=23&a=1','Primary'),S('John Calvin','Institutes III.21–24','https://www.ccel.org/ccel/calvin/institutes.iii.xxi.html','Primary'),S('Formula of Concord','Solid Declaration XI','https://bookofconcord.org/formula-of-concord/solid-declaration/election/','Confession'),S('Westminster Confession','Chapter 3','https://wts.edu/wcf','Confession'),S('Canons of Dort','First Head','https://www.ccel.org/creeds/canons-of-dort.html','Confession'),S('John Cassian','Conferences','https://www.newadvent.org/fathers/3501.htm','Primary Eastern witness'),S('Catechism of the Catholic Church','§§600–605','https://www.vatican.va/content/catechism/en/part_one/section_two/chapter_two/article_3/iv_died_for_our_sins.html','Secondary synthesis')]},

    'faith-works':{domain:'Justification & Sanctification',title:'Faith & Works',centralQuestion:'If salvation is by grace, what place remains for obedience, charity, and good works?',definition:'Faith and works names the relationship between trusting Christ and the obedient life that follows. The New Testament speaks of justification by faith and also declares that faith without works is dead. Classical Christianity agrees that genuine faith produces love; the major disagreement concerns whether works belong within the believer’s justification, or only as its necessary fruit.',lead:'The Catholic and Orthodox traditions tend to describe faith as living participation that cannot be separated from charity and obedience. Lutheran and Reformed theology insists that faith alone is the instrument of justification, while equally insisting that justifying faith is never alone. The crucial distinction is therefore between the ground or instrument of acceptance with God and the transformed life that necessarily follows.',questions:['What does Paul mean by justification by faith?','What does James mean by faith without works?','Are works causes, conditions, fruits, or evidence of justification?','Can works done in grace merit reward?','How should faith, charity, and sanctification be ordered?'],traditions:[
      T('catholic','Catholic','Faith is the beginning and root of justification, but living faith is formed by charity; works done in grace belong to the Christian’s growth in righteousness.',[
        'Catholic theology denies that fallen humanity can earn initial justification. Grace precedes and creates faith. Yet once the person is justified, the Holy Spirit truly transforms the person, and acts of charity become genuine acts of the renewed believer.',
        'Trent therefore distinguishes initial justification from increase in justification. Good works are not rival causes alongside Christ; they are fruits of Christ’s grace in the believer. Merit is always dependent on grace and Christ’s prior merits.',
        'Paul and James are reconciled by distinguishing dead faith from living faith. Paul rejects works of the law as grounds for boasting; James rejects a verbal faith that produces no obedience.'
      ],'The Catholic account protects both gratuity and transformation. If grace really makes a person righteous, the person’s subsequent acts cannot be treated as irrelevant to the life of salvation.', 'Lutheran and Reformed critics argue that including works within an account of increasing justification risks confusing the ground of acceptance with the fruit of salvation.', 'Catholic theology answers that merit is derivative and that Christ remains the sole source of supernatural grace. The believer’s works are God’s gifts working through a real human agent.', ['Augustine','Thomas Aquinas','Council of Trent']),
      T('orthodox','Eastern Orthodox','Faith is living trust and communion with Christ; works of love are the concrete expression of a faith being healed and deified.',[
        'Orthodox theology generally resists turning faith and works into separate quantities. Faith is personal fidelity, not mere intellectual assent. Repentance, prayer, fasting, mercy, Eucharistic communion, and ascetic struggle are therefore expressions of living faith.',
        'The believer’s works do not purchase God’s favor. They are the activity of a person cooperating with grace. Synergy means that the person genuinely acts because God has first enabled and sustained the action.',
        'James is therefore straightforward: a faith that never becomes life is not saving faith. Paul’s rejection of boasting is read as a rejection of self-righteousness, not of obedience.'
      ],'The Orthodox account places faith within the whole therapeutic and sacramental life rather than isolating it as one mental act that produces a legal verdict.', 'Protestant theology worries that this makes the basis of assurance depend on the believer’s progress.', 'Orthodox theology answers that assurance is trust in God’s mercy, while salvation remains a lifelong participation in grace rather than a one-time psychological certainty.', ['John Chrysostom','Maximus the Confessor','John Climacus']),
      T('lutheran','Lutheran','Faith alone receives justification, but the faith that receives Christ is living and necessarily produces good works.',[
        'The Lutheran distinction is between justification and sanctification. Faith receives Christ and His righteousness; works follow as the necessary fruit of that faith. Works are commanded by God and genuinely good, but they do not reconcile the sinner to God.',
        'The Augsburg Confession explicitly rejects the charge that sola fide means that Christians should do no good works. The issue is not whether works matter, but what they do in relation to justification.',
        'This protects assurance. The sinner looks to Christ’s promise rather than measuring the sufficiency of personal obedience.'
      ],'The Lutheran argument preserves the Gospel as pure gift. If works become part of the basis of justification, the sinner is pushed back toward self-measurement.', 'Catholic and Orthodox critics argue that a strict separation can make James sound secondary and can understate the biblical language of growth in righteousness.', 'Lutheran theology answers that sanctification is real and necessary; it simply must not be confused with the verdict by which God accepts the sinner.', ['Martin Luther','Philip Melanchthon','Formula of Concord']),
      T('reformed','Reformed','Faith alone justifies, but justifying faith is never alone; union with Christ necessarily produces sanctification and good works.',[
        'Calvin rejects a merely intellectual faith. Faith unites the believer to Christ, and union with Christ brings both justification and sanctification. The two benefits are distinct but inseparable.',
        'The Westminster Confession teaches that good works are fruits and evidences of a true and living faith. They cannot merit pardon or eternal life, yet God is pleased to reward them in believers because He graciously accepts them in Christ.',
        'Reformed theology therefore avoids antinomianism while preserving sola fide. Works reveal the reality of faith rather than becoming the basis of the initial verdict.'
      ],'The Reformed account protects the forensic character of justification while giving sanctification a necessary place in the believer’s union with Christ.', 'Catholic theology argues that the Protestant distinction can be too sharp and that Scripture speaks of growth in righteousness and final judgment according to works.', 'Reformed theology answers that final judgment according to works displays the fruit of faith rather than changing the ground of justification.', ['John Calvin','John Owen','Westminster Assembly'])
    ],clashes:['Faith alone as instrument versus faith formed by charity.','Works as fruit and evidence versus works as part of increase in justification.','Final judgment according to works and its relation to justification.','Assurance grounded in Christ’s promise versus assurance informed by transformed life.'],history:[H('c. 400','Augustine','Faith, grace, charity, and works are held together within a transformative account of salvation.','Augustine becomes foundational to later Catholic and Protestant readings.'),H('13th century','Aquinas','Faith is the beginning of justification and charity perfects the life of grace.','Scholastic theology develops distinctions concerning merit and charity.'),H('1518–1521','Luther','Sola fide becomes central to Reformation controversy.','Justification is sharply distinguished from works as a ground of acceptance.'),H('1530','Augsburg Confession','Lutheran confession explains justification and the necessity of good works.','Faith alone is explicitly separated from antinomianism.'),H('1547','Council of Trent','Trent defines justification, increase in righteousness, and merit.','The Catholic response becomes a major point of doctrinal divergence.'),H('1640s','Westminster Confession','Reformed theology formulates faith alone with a strong doctrine of necessary works.','The confession clarifies the relation between justification and sanctification.')],sources:[S('Paul','Romans and Galatians','texts/bible.html','Primary Scripture'),S('James','Epistle of James','texts/bible.html','Primary Scripture'),S('Augustine','On Faith and Works','https://www.newadvent.org/fathers/1505.htm','Primary'),S('Thomas Aquinas','Summa I-II, qq.109–114','texts/summa.html?part=prima-sec&q=109&a=1','Primary'),S('Augsburg Confession','Articles IV and XX','https://bookofconcord.org/augsburg-confession/','Confession'),S('Council of Trent','Session VI','https://www.newadvent.org/cathen/15030c.htm','Primary council'),S('John Calvin','Institutes III.16–18','https://www.ccel.org/ccel/calvin/institutes.iii.xvi.html','Primary'),S('Westminster Confession','Chapters 11, 13, 16','https://wts.edu/wcf','Confession')]}
  };

  function esc(x){return String(x==null?'':x).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\\':'&#92;'}[c]));}
  function linkify(name){return esc(name);}
  function render(data){
    const trads=data.traditions||[];
    let h='<header class="exhibit-hero" id="exhibit-top"><div class="exhibit-hero-inner"><a class="exhibit-back" href="concepts.html">← All Concepts</a><span class="exhibit-eyebrow">'+esc(data.domain)+'</span><h1>'+esc(data.title)+'</h1><p class="exhibit-question">'+esc(data.centralQuestion)+'</p><p class="exhibit-definition">'+esc(data.definition)+'</p><p class="exhibit-lead">'+esc(data.lead)+'</p></div></header>';
    h+='<section class="exhibit-section" id="questions"><span class="exhibit-kicker">The question</span><h2>What is really at stake?</h2><div class="question-grid">'+(data.questions||[]).map((q,i)=>'<div class="question-card"><span>0'+(i+1)+'</span><p>'+esc(q)+'</p></div>').join('')+'</div></section>';
    h+='<section class="exhibit-section" id="glance"><span class="exhibit-kicker">Comparison</span><h2>'+esc(data.title)+' at a Glance</h2><div class="tradition-grid">'+trads.map(t=>'<article class="tradition-summary trad-'+esc(t.key)+'"><span class="trad-badge">'+esc(t.name)+'</span><h3>'+esc(t.thesis)+'</h3><p>'+esc(t.account[0])+'</p><a href="#trad-'+esc(t.key)+'">Read the full account ↓</a></article>').join('')+'</div></section>';
    h+='<section class="exhibit-section" id="traditions"><span class="exhibit-kicker">The traditions</span><h2>Four Ways of Seeing the Mystery</h2>';
    trads.forEach(t=>{h+='<article class="tradition-dossier" id="trad-'+esc(t.key)+'"><div class="tradition-heading"><span class="trad-badge">'+esc(t.name)+'</span><h2>'+esc(t.thesis)+'</h2></div><div class="dossier-body"><div><h3>The account</h3>'+t.account.map(p=>'<p>'+esc(p)+'</p>').join('')+'</div><aside><div class="tradition-panel"><h3>Why this makes sense</h3><p>'+esc(t.argument)+'</p></div><div class="tradition-panel"><h3>Strongest objection</h3><p>'+esc(t.objection)+'</p></div><div class="tradition-panel"><h3>The response</h3><p>'+esc(t.response)+'</p></div><div class="tradition-panel"><h3>Key witnesses</h3><p>'+t.figures.map(linkify).join(' · ')+'</p></div></aside></div></article>';});
    h+='</section><section class="exhibit-section" id="clashes"><span class="exhibit-kicker">The fault lines</span><h2>Where the Traditions Actually Clash</h2><div class="clash-stack">'+(data.clashes||[]).map((c,i)=>'<div class="clash-card"><span class="clash-number">'+String(i+1).padStart(2,'0')+'</span><p>'+esc(c)+'</p></div>').join('')+'</div></section>';
    h+='<section class="exhibit-section" id="history"><span class="exhibit-kicker">Development</span><h2>The History of the Debate</h2><div class="timeline">'+(data.history||[]).map(n=>'<div class="timeline-node"><div class="timeline-date">'+esc(n.date)+'</div><div class="timeline-title">'+esc(n.title)+'</div><p class="timeline-sig">'+esc(n.significance)+'</p>'+(n.extra?'<details><summary>Read more</summary><p class="timeline-extra">'+esc(n.extra)+'</p></details>':'')+'</div>').join('')+'</div></section>';
    h+='<section class="exhibit-section" id="sources"><span class="exhibit-kicker">Primary & secondary sources</span><h2>Read the Tradition in Its Own Voice</h2><p class="exhibit-lead" style="margin-top:0;margin-bottom:1.5rem">Primary texts are the foundation. Confessions, councils, liturgical witnesses, and established theological syntheses are included so that each tradition can be understood on its own terms before comparison.</p><div class="source-grid">'+(data.sources||[]).map(s=>'<a class="source-card" href="'+esc(s.href)+'"'+(/^https?:/i.test(s.href)?' target="_blank" rel="noopener"':'')+'><span class="src-author">'+esc(s.author)+'</span><span class="src-title">'+esc(s.title)+'</span><span class="src-meta"><span>'+esc(s.note)+'</span></span></a>').join('')+'</div></section>';
    const related=(global.CONCEPTS||[]).filter(c=>c.id!==data.id).slice(0,8); h+='<section class="exhibit-section" id="thread"><span class="exhibit-kicker">Connections</span><h2>Follow the Thread</h2><div class="related-chips">'+related.map(r=>'<a href="concept.html?id='+encodeURIComponent(r.id)+'">'+esc(r.name)+'</a>').join('')+'</div></section><p class="exhibit-footnote">Lumen Fidei presents classical positions for study. The traditions are internally diverse; these entries describe their principal classical forms and identify the points where their doctrinal claims genuinely differ.</p>';
    return h;
  }
  function setup(sections){const nav=document.getElementById('exhibit-progress'),inner=document.getElementById('exhibit-progress-inner');if(!nav||!inner)return;inner.innerHTML=sections.map(s=>'<a href="#'+s.id+'" data-section="'+s.id+'">'+s.label+'</a>').join('');nav.hidden=false;const links=inner.querySelectorAll('a');function onScroll(){let active=sections[0]?.id;const y=scrollY+140;sections.forEach(s=>{const e=document.getElementById(s.id);if(e&&e.offsetTop<=y)active=s.id;});links.forEach(a=>a.classList.toggle('is-active',a.dataset.section===active));}addEventListener('scroll',onScroll,{passive:true});onScroll();}
  const ids=Object.keys(D); const old=global.ConceptExhibit||{}; const exhibits=Object.assign({}, old && old.EXHIBITS ? old.EXHIBITS : {}, D);
  global.ConceptExhibit=Object.assign({},old,{DEEP:D,hasExhibit:id=>!!(old.hasExhibit&&old.hasExhibit(id))||!!D[id],mount:(root,id)=>{if(D[id]){document.body.classList.add('has-exhibit');document.title=D[id].title+' — Concepts — Lumen Fidei';root.innerHTML=render(D[id]);setup([{id:'questions',label:'Question'},{id:'glance',label:'At a Glance'},{id:'traditions',label:'Traditions'},{id:'clashes',label:'Fault Lines'},{id:'history',label:'History'},{id:'sources',label:'Sources'},{id:'thread',label:'Connections'}]);} else if(old.mount) old.mount(root,id);}});
})(window);
